// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.estimation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

/**
 * A planner probe of the legacy quad synopsis runs as an optimistic read while commits keep adding rows to the mutable
 * delta. Nothing an optimistic read computes may escape before the read is validated: a probe that raced an addition
 * must be retried under the read lock rather than fail the planner with an exception from torn state.
 */
class BoundedQuadSynopsisConcurrentProbeTest {

	private static final QuadSnapshotIdentity IDENTITY = new QuadSnapshotIdentity(17L, 23L, 5L);
	private static final long PREDICATE = 42L;
	private static final int READERS = 3;
	private static final int ROUNDS = 12;

	@Test
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void optimisticProbesNeverFailWhileAdditionsGrowTheDeltaSample() throws Exception {
		QuadSynopsisBudget budget = QuadSynopsisBudget.create(4L * 1024L * 1024L, 128);
		int rowsPerRound = Math.min(budget.deltaSampleCapacity(), 12_000);
		QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L, PREDICATE, 0L, 0L, IDENTITY);
		List<Throwable> failures = new ArrayList<>();
		AtomicLong probes = new AtomicLong();
		for (int round = 0; round < ROUNDS && failures.isEmpty(); round++) {
			BoundedQuadSynopsis synopsis = new BoundedQuadSynopsis(
					new QuadSynopsisBuilder(budget, IDENTITY, 1L).build(), budget, () -> {
					});
			AtomicBoolean writing = new AtomicBoolean(true);
			CountDownLatch started = new CountDownLatch(READERS);
			List<Thread> readers = new ArrayList<>();
			for (int reader = 0; reader < READERS; reader++) {
				Thread thread = Thread.ofPlatform().name("quad-synopsis-probe-" + reader).start(() -> {
					started.countDown();
					try {
						while (writing.get()) {
							synopsis.probe(probe);
							probes.incrementAndGet();
						}
					} catch (Throwable failure) {
						synchronized (failures) {
							failures.add(failure);
						}
					}
				});
				readers.add(thread);
			}
			assertTrue(started.await(30L, TimeUnit.SECONDS));
			for (int row = 0; row < rowsPerRound; row++) {
				synopsis.add(1_000_000L + round * 100_000L + row, PREDICATE, 2_000_000L + row, 0L);
			}
			writing.set(false);
			for (Thread reader : readers) {
				reader.join(TimeUnit.SECONDS.toMillis(30L));
			}
			assertEquals(rowsPerRound, synopsis.probe(probe).rows().estimate(), 0.0d,
					"after the writer stops, a validated probe sees every added row");
		}
		assertTrue(failures.isEmpty(), "a probe that raced an addition escaped its optimistic read with "
				+ failures.size() + " failure(s) over " + probes.get() + " probes; first: "
				+ (failures.isEmpty() ? "" : failures.get(0)));
	}
}
